const {test}=require('node:test'),assert=require('node:assert/strict');
const {createResourceRuntime}=require('./d1-resource-runtime.cjs');
function options(){return{aws:async()=>assert.fail('AWS called'),cloudflare:async()=>assert.fail('Cloudflare called'),lambda:async()=>assert.fail('Lambda called'),github:async()=>assert.fail('GitHub called'),plans:{load:async()=>null,save:async()=>{}},run:'a'.repeat(32),source:'b'.repeat(40),executorToken:'c'.repeat(64),definitionSha256:'d'.repeat(64),directory:'/private/owned',assertRuntime:async()=>assert.fail('Runtime called'),assertRecoveryLease:async()=>assert.fail('Recovery lease called')};}
test('composed runtime defaults disabled before any provider read, claim or recovery',async()=>{const runtime=createResourceRuntime(options());for(const action of ['claim','advance','complete','abort'])await assert.rejects(runtime[action](),/RUNTIME_DISABLED/);});
test('missing runtime/recovery-lease callbacks or private context refuse construction',()=>{for(const override of [{assertRuntime:undefined},{assertRecoveryLease:undefined},{executorToken:undefined},{enabled:'true'},{enabled:true,token:'short'},{enabled:true,token:'synthetic-resource-token-0123456789\n'}])assert.throws(()=>createResourceRuntime({...options(),...override}));});
